const select=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const format=n=>Number(n).toLocaleString('es-CL');
const map=select('#demo-map');
map.innerHTML=`<defs><clipPath id="preview-land"><path d="${CHILE_MAP.path}"/></clipPath></defs><path d="${CHILE_MAP.path}" fill="#365569"/><g clip-path="url(#preview-land)">${CHILE_MAP.cells.map(([x,y])=>`<rect class="preview-cell" x="${x}" y="${y}" width="${CHILE_MAP.step+.05}" height="${CHILE_MAP.step+.05}" fill="#365569" stroke="#7696ac" stroke-width=".5"/>`).join('')}</g><path d="${CHILE_MAP.path}" fill="none" stroke="#c5dce8" stroke-width="1.2" stroke-linejoin="round"/>`;
const mapCells=all('.preview-cell');
const demoColors=[],demoRows=new Map();CHILE_MAP.cells.forEach(([x,y],i)=>{const key=y+':'+(x<95?'island':'main');if(!demoRows.has(key))demoRows.set(key,[]);demoRows.get(key).push({x,i})});demoRows.forEach(row=>{row.sort((a,b)=>a.x-b.x);row.forEach((cell,i)=>demoColors[cell.i]=['#155cb1','#ffffff','#e43f45'][row.length<=2?(i===0?0:2):Math.min(2,Math.floor(i*3/row.length))])});
function previewProgress(){const count=Number(select('#journey-range').value),fraction=count/1000000;select('#demo-count').textContent=format(count);select('#demo-percent').textContent=Math.round(fraction*100)+' %';select('#demo-progress').style.width=fraction*100+'%';select('#journey-range').setAttribute('aria-valuetext',format(count)+' daimoku, '+Math.round(fraction*100)+' por ciento del mapa');mapCells.forEach((cell,i)=>cell.setAttribute('fill',i<Math.floor(fraction*1000)?demoColors[i]:'#365569'));select('#demo-region').textContent=count===1000000?'Un horizonte completo':count>=850000?'Patagonia':count>=700000?'Los lagos y el sur':count>=550000?'Centro Sur':count>=400000?'Zona Central':count>=250000?'Norte Chico':'Norte Grande'}
select('#journey-range').oninput=previewProgress;previewProgress();
const instructions={android:[['Abre en Chrome.','Visita esta página desde tu teléfono Android.'],['Busca la opción Instalar.','En el menú de tres puntos, busca «Instalar y crear acceso directo» y luego «Instalar», o «Añadir a pantalla de inicio».'],['Haz espacio para tu práctica.','Confirma y abre Daimoku Chile desde su ícono.']],ios:[['Abre en Safari.','Visita esta página en tu iPhone o iPad.'],['Pulsa Compartir.','Busca «Añadir a pantalla de inicio». Si aparece la opción «Abrir como app web», actívala.'],['Confirma con Añadir.','Daimoku Chile quedará en tu pantalla de inicio. Ábrela desde su ícono para comenzar.']],desktop:[['Abre en Chrome o Edge.','Visita esta página desde tu computador.'],['Busca la opción Instalar.','Usa el ícono de instalación junto a la barra de direcciones o la opción Instalar del menú del navegador.'],['Abre tu espacio.','Confirma la instalación. También puedes usarla directamente en el navegador.']]};
function showDevice(device,focus=false){if(!instructions[device])device='android';all('[data-device]').forEach(tab=>{const selected=tab.dataset.device===device;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1;if(selected&&focus)tab.focus()});select('#device-instructions').setAttribute('aria-labelledby','tab-'+device);select('#device-instructions').innerHTML='<ol>'+instructions[device].map(([title,body],i)=>`<li><span>${i+1}</span><div><strong>${title}</strong><p>${body}</p></div></li>`).join('')+'</ol>'}
all('[data-device]').forEach(tab=>{tab.onclick=()=>showDevice(tab.dataset.device);tab.onkeydown=e=>{const tabs=all('[data-device]'),i=tabs.indexOf(tab);let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();showDevice(tabs[next].dataset.device,true)}}});
const agent=navigator.userAgent,isIOS=/iPad|iPhone|iPod/.test(agent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);showDevice(isIOS?'ios':/Android/i.test(agent)?'android':'desktop');
let pendingInstall=null;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();pendingInstall=event;select('#install-status').textContent='Tu navegador permite instalarla. Pulsa el botón para continuar.'});
select('#install-now').onclick=async()=>{if(pendingInstall){const prompt=pendingInstall;pendingInstall=null;try{await prompt.prompt();const result=await prompt.userChoice;select('#install-status').textContent=result.outcome==='accepted'?'Instalación solicitada. Sigue las indicaciones de tu navegador.':'Puedes instalarla después o comenzar desde el navegador.'}catch{select('#install-status').textContent='Usa el menú de tu navegador y sigue los pasos de esta sección.'}}else{select('#install-status').textContent=isIOS?'En Safari, pulsa Compartir y luego «Añadir a pantalla de inicio».':'Usa el menú de tu navegador para instalarla. Los pasos están a continuación.';select('.install-instructions').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});select('[data-device][aria-selected="true"]').focus({preventScroll:true})}};
window.addEventListener('appinstalled',()=>{pendingInstall=null;select('#install-status').textContent='La aplicación se instaló. Ábrela desde su ícono para comenzar.'});
function escapeHtml(value){const span=document.createElement('span');span.textContent=value;return span.innerHTML}
select('#photo-credits').onclick=()=>{select('#landing-credits').innerHTML=[0,3,6].map(i=>{const photo=REGION_PHOTOS[i];return `<article><h3>${escapeHtml(photo.place)}</h3>${escapeHtml(photo.artist)} · <a target="_blank" rel="noopener" href="${photo.page}">Wikimedia Commons</a> · ${photo.licenseUrl?`<a target="_blank" rel="noopener" href="${photo.licenseUrl}">${escapeHtml(photo.license)}</a>`:escapeHtml(photo.license)}</article>`}).join('');select('#credits-dialog').showModal()};select('#close-credits').onclick=()=>select('#credits-dialog').close();select('#credits-dialog').onclick=e=>{if(e.target===select('#credits-dialog'))select('#credits-dialog').close()};
select('#privacy-link').onclick=()=>{const details=all('.faq-list details');details[0].open=true;details[1].open=true};
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
